import {attr, controller, target} from '@github/catalyst'
import {SinglePageWizardStepContentBase} from '../../single-page-wizard/step-content-base'
import type {StepChangeResult} from '../../single-page-wizard/wizard'
import type {TwoFactorWizardState} from './wizard-state'
import {getBaseFetchHeaders} from '@github-ui/fetch-headers'

@controller
class TwoFactorSetupRecoveryCodesElement extends SinglePageWizardStepContentBase {
  @attr declare errorMessage: string
  @target declare codes: HTMLElement
  @target declare form: HTMLFormElement
  @target declare downloadCodesForm: HTMLFormElement
  declare wizardState: TwoFactorWizardState

  override async setStepState(wizardState: TwoFactorWizardState) {
    this.wizardState = wizardState

    this.codes.textContent = ''
    if (this.wizardState.formatted_recovery_codes) {
      for (const code of this.wizardState.formatted_recovery_codes) {
        const li = document.createElement('li')
        li.textContent = code
        li.className = 'two-factor-recovery-code'
        this.codes.appendChild(li)
      }
    }
  }

  override async onNextClick(): Promise<StepChangeResult<TwoFactorWizardState>> {
    const csrfInput = this.form.querySelector('.js-data-url-csrf') as HTMLInputElement
    const formData = new FormData()
    formData.append('type', this.wizardState.type!)

    this.clearError()
    const response = await fetch(this.form.action, {
      mode: 'same-origin',
      method: 'POST',
      body: formData,
      headers: {
        Accept: 'application/json',
        'Scoped-CSRF-Token': csrfInput.value,
        ...getBaseFetchHeaders(),
      },
    })

    if (!response.ok) {
      const json = await response.json()
      if (json.error) {
        this.setError(json.error)
      } else {
        this.setError(this.errorMessage)
      }
      return {proceed: false}
    }

    const reconfigNotification = document.getElementById('two-factor-reconfigure-notification')
    if (reconfigNotification) {
      const dismissButton = reconfigNotification.querySelector('.js-flash-close')
      if (dismissButton) {
        ;(dismissButton as HTMLButtonElement).click()
      }
    }

    return {proceed: true}
  }

  async onDownloadClick() {
    // put an element on the page that single-page-wizard/wizard.ts checks for
    // before applying the onbeforeunload "are you sure" dialog
    // this element is automatically removed in the wizard.ts code
    const ignoreWarningElem = document.createElement('div')
    ignoreWarningElem.id = 'one-off-ignore-single-page-wizard-warning'
    document.body.appendChild(ignoreWarningElem)
    this.downloadCodesForm.submit()

    this.validateStep(true)
    return {proceed: true}
  }

  override isStepValid(): boolean {
    return false
  }
}
